    {"id":"mianmian_matcha","no":518,"name":"绵绵抹茶刨冰","emoji":"🍵","origin":"台湾","ingredients":["red_bean","matcha","cream"],"method":"freeze","hint":"像羽毛一样的绿色雪，下面藏着甜甜的豆沙。","recipePrice":300,"sellPrice":150,"story":"原名 綿綿冰 抹茶 Miánmián bīng（汉语）。绵绵冰是用牛奶冻成冰块再刨出来的，像雪一样轻、像奶一样绵。抹茶的清苦配红豆的甜，是最经典的搭配。"},
    {"id":"mianmian_strawberry","no":519,"name":"绵绵草莓刨冰","emoji":"🍓","origin":"台湾","ingredients":["cream","strawberry","condensed_milk"],"method":"freeze","hint":"粉白的奶雪堆成小山，上面淋着红红的果酱。","recipePrice":340,"sellPrice":170,"story":"原名 綿綿冰 草莓 Miánmián bīng（汉语）。绵绵的奶雪上盖着草莓，再淋一圈炼乳，吃到最后碗底是一汪甜甜的粉色牛奶。"},
    {"id":"mianmian_pear","no":520,"name":"绵绵梨子刨冰","emoji":"🍐","origin":"台湾","ingredients":["cream","milk","pear"],"method":"freeze","hint":"洁白的奶雪里，埋着一块块清脆多汁的小方块。","recipePrice":320,"sellPrice":160,"story":"原名 綿綿冰 梨子 Miánmián bīng（汉语）。奶雪的绵软和梨的清脆在嘴里同时出现，一口软、一口脆，是最让人上瘾的口感。"},
    {"id":"mianmian_grape","no":521,"name":"绵绵葡萄刨冰","emoji":"🍇","origin":"台湾","ingredients":["cream","grape","muscat"],"method":"freeze","hint":"白雪上落着紫色和翠绿色的葡萄，像宝石撒在奶油上。","recipePrice":360,"sellPrice":180,"story":"原名 綿綿冰 葡萄 Miánmián bīng（汉语）。紫葡萄和翠绿的麝香葡萄一起铺在奶雪上，像一把宝石撒在雪地里，一口一颗，甜得清爽。"},
    {"id":"mianmian_chocolate","no":522,"name":"绵绵巧克力刨冰","emoji":"🍫","origin":"台湾","ingredients":["cream","raw_chocolate","chocolate"],"method":"freeze","hint":"深褐色的酱汁淋在白雪上，浓得像冬天的热巧克力。","recipePrice":340,"sellPrice":170,"story":"原名 綿綿冰 巧克力 Miánmián bīng（汉语）。浓稠的巧克力酱淋在细腻的奶雪上，一边融化一边吃，是巧克力控的终极甜点。"},
    {"id":"shirokuma","no":523,"name":"白熊刨冰","emoji":"🐻‍❄️","city":"japan","ingredients":["milk","condensed_milk","canned_fruit"],"method":"freeze","hint":"白色的雪山上，水果摆成一张笑脸，像一只北极熊。","recipePrice":300,"sellPrice":150,"story":"原名 しろくま（日语）。白熊刨冰来自日本九州，炼乳淋成白色的雪山，上面用各种水果摆出熊的脸。小朋友总会先挑掉水果，把“眼睛”留到最后。"},
    {"id":"mianmian_kuromitsu_kinako","no":524,"name":"黑糖浆绵绵黄豆粉刨冰","emoji":"🟤","origin":"台湾","ingredients":["milk","cream","kuromitsu"],"method":"freeze","hint":"黑亮的糖浆淋在白雪上，焦香得像旧时光的味道。","recipePrice":310,"sellPrice":155,"story":"原名 黑糖浆黃豆粉綿綿冰 Miánmián bīng（汉语）。黑糖浆的焦香和奶雪的清甜，再撒上黄豆粉，是怀旧的味道，像外婆家夏天的下午。"},
    {"id":"mianmian_cheese_lemon","no":525,"name":"绵绵芝士柠檬刨冰","emoji":"🍋","origin":"台湾","ingredients":["milk","cheese","lemon"],"method":"freeze","hint":"奶香里透着柠檬的清酸，像芝士蛋糕变成了雪。","recipePrice":300,"sellPrice":150,"story":"原名 綿綿冰 芝士檸檬 Miánmián bīng（汉语）。奶酪的浓郁被柠檬的清酸托着，绵绵的雪里像藏着一块冻芝士蛋糕，酸酸甜甜又不腻。"},
    {"id":"mianmian_milktea","no":526,"name":"绵绵奶茶刨冰","emoji":"🧋","origin":"台湾","ingredients":["milk","cream","tea_leaf"],"method":"freeze","hint":"茶色的雪，带着熟悉的奶茶香，一口下去是凉凉的奶茶。","recipePrice":340,"sellPrice":170,"story":"原名 綿綿冰 奶茶 Miánmián bīng（汉语）。把奶茶冻成冰再刨成雪，一口下去是熟悉的茶香和奶香。是不想喝冷饮、又想吃奶茶的人的选择。"},
    {"id":"mianmian_mango","no":527,"name":"绵绵芒果刨冰","emoji":"🥭","origin":"台湾","ingredients":["milk","cream","mango"],"method":"freeze","hint":"金黄的果肉盖在雪白的冰上，像夏天的太阳落在雪山上。","recipePrice":340,"sellPrice":170,"story":"原名 綿綿冰 芒果 Miánmián bīng（汉语）。芒果冰是台湾夏天的代表，金黄饱满的芒果铺在奶雪上，甜得很满足。"},
    {"id":"mianmian_sesame_penguin","no":528,"name":"黑芝麻企鹅刨冰","emoji":"🐧","origin":"台湾","ingredients":["milk","cream","black_sesame"],"method":"freeze","hint":"黑白相间的小企鹅，肚子是雪白的，头顶是黑黑的。","recipePrice":280,"sellPrice":140,"story":"原名 黑芝麻企鵝綿綿冰 Miánmián bīng（汉语）。黑芝麻磨成浆染黑了企鹅的背，雪白的奶雪是它的肚皮。圆滚滚的小企鹅看着舍不得下勺，吃起来香得有点上头。"},
    {"id":"blacktea_softcream","no":529,"name":"红茶软冰淇淋","emoji":"🍦","origin":"世界","ingredients":["tea_leaf","gelatin","milk"],"method":"freeze","hint":"浅棕色的软软冰淇淋，茶香浓浓的，尾调有一点涩。","recipePrice":300,"sellPrice":150,"story":"原名 Black tea soft serve（英语）。红茶的香气融进软软的牛奶冰里，入口是奶香，咽下去是茶香，像把下午茶冻成了一座小山。"},
    {"id":"blacktea_soy_pudding","no":530,"name":"红茶豆乳布丁","emoji":"🍮","city":"japan","ingredients":["soy_milk","tea_leaf","gelatin"],"method":"freeze","hint":"颤巍巍的浅棕色布丁，茶香里有豆子的温柔。","recipePrice":250,"sellPrice":125,"story":"原名 紅茶豆乳プリン（日语）。豆乳的温柔配上红茶的香气，凝成颤巍巍的一块。不用鸡蛋也很顺滑，是甜点里清清淡淡的那一位。"},
    {"id":"blacktea_roll","no":531,"name":"红茶蛋糕卷","emoji":"🍰","city":"japan","ingredients":["tea_leaf","wheat_flour","cream"],"method":"cook","hint":"一圈圈卷起来的浅棕色蛋糕，切开能看到白色的奶油螺旋。","recipePrice":200,"sellPrice":100,"story":"原名 紅茶ロールケーキ（日语）。茶叶磨细加进蛋糕体，卷上白白的奶油，切开是一圈圈的茶色和奶色。配一杯热红茶，最是舒服。"},
    {"id":"bubble_milk_tea","no":532,"name":"珍珠奶茶","emoji":"🧋","origin":"台湾","ingredients":["tea_leaf","milk","tapioca"],"method":"drink","hint":"一杯茶色的奶茶，吸管吸起来，会一颗颗弹进嘴里。","recipePrice":190,"sellPrice":95,"story":"原名 珍珠奶茶 Zhēnzhū nǎichá（汉语）。1980 年代诞生在台湾，黑色的珍珠Q弹有嚼劲，混着浓浓的奶茶，是现在全世界都认识的味道。"},
    {"id":"bubble_matcha_milk_tea","no":533,"name":"抹茶珍珠奶茶","emoji":"🍵","origin":"台湾","ingredients":["tapioca","milk","matcha"],"method":"drink","hint":"绿色的奶茶里沉着黑黑的小球，苦香和软糯一起上来。","recipePrice":190,"sellPrice":95,"story":"原名 抹茶珍珠奶茶 Mǒchá zhēnzhū nǎichá（汉语）。抹茶的清苦让珍珠奶茶的甜变得有分寸，绿色的杯子里沉着黑色的珍珠，是抹茶控的特别选择。"},
    {"id":"bubble_choco_mint_latte","no":534,"name":"珍珠巧克力薄荷拿铁","emoji":"🍫","origin":"世界","ingredients":["tapioca","mint","chocolate"],"method":"drink","hint":"清凉的薄荷香和浓浓的巧克力，里面还藏着软糯的小球。","recipePrice":160,"sellPrice":80,"story":"原名 Bubble chocolate mint latte（英语）。薄荷的清凉盖过了巧克力的腻，里面的珍珠又Q又软。是爱薄荷巧克力的人，会反复点的一杯。"},
    {"id":"bubble_mango_drink","no":535,"name":"珍珠芒果饮","emoji":"🥭","origin":"世界","ingredients":["tapioca","mango","cream"],"method":"drink","hint":"金黄的芒果浆，顶着一层奶油，吸管里夹着软软的小球。","recipePrice":220,"sellPrice":110,"story":"原名 Bubble mango drink（英语）。芒果的浓甜配上奶油的顺滑，再加上Q弹的珍珠。吸一口，是热带的味道。"},
    {"id":"bubble_coffee_float","no":536,"name":"珍珠咖啡雪顶","emoji":"☕","origin":"世界","ingredients":["tapioca","vanilla_icecream","coffee_bean"],"method":"drink","hint":"黑色的咖啡上顶着白色的冰淇淋，底下沉着软糯的珍珠。","recipePrice":200,"sellPrice":100,"story":"原名 Bubble coffee float（英语）。冰淇淋慢慢融进咖啡，苦和甜在杯子里慢慢混合，底下的珍珠最后一口才吸到。"},
    {"id":"brown_sugar_cheese_tea","no":537,"name":"黑糖牛奶芝士茶","emoji":"🧋","origin":"台湾","ingredients":["kuromitsu","milk","cheese"],"method":"drink","hint":"黑糖的焦香，牛奶的顺滑，上面盖着一层咸咸的奶盖。","recipePrice":190,"sellPrice":95,"story":"原名 黑糖鮮奶芝士茶 Hēitáng xiānnǎi zhīshì chá（汉语）。黑糖浆在杯壁拉出一道道虎纹，上面盖着咸香的奶盖。要不用吸管，直接喝，才能同时尝到咸和甜。"},
    {"id":"strawberry_cheese_tea","no":538,"name":"草莓芝士茶","emoji":"🍓","origin":"台湾","ingredients":["tea_leaf","strawberry","cheese"],"method":"drink","hint":"红红的果肉、茶香、顶上盖着奶盖，酸甜咸交织在一起。","recipePrice":230,"sellPrice":115,"story":"原名 草莓芝士茶 Cǎoméi zhīshì chá（汉语）。新鲜草莓压碎垫在杯底，淋上茶汤，再盖一层咸奶盖。酸、甜、咸、茶香，一口喝到四种味道。"},
    {"id":"cheese_matcha_latte","no":539,"name":"芝士抹茶拿铁","emoji":"🍵","origin":"台湾","ingredients":["matcha","milk","cheese"],"method":"drink","hint":"绿色的拿铁，顶着一层白色的咸奶盖，苦香里有咸香。","recipePrice":220,"sellPrice":110,"story":"原名 芝士抹茶拿鐵 Zhīshì mǒchá nátiě（汉语）。抹茶拿铁上盖一层咸味奶盖，先喝到奶盖的咸香，再喝到抹茶的清苦，两种味道在嘴里交替。"},
    {"id":"choco_mint_icecream","no":540,"name":"巧克力薄荷冰淇淋","emoji":"🍨","origin":"美国","ingredients":["chocolate","mint","cream"],"method":"freeze","hint":"淡绿色的冰淇淋里嵌着黑黑的碎片，凉到鼻腔里去。","recipePrice":310,"sellPrice":155,"story":"原名 Mint chocolate chip（英语）。淡绿色的薄荷冰淇淋里嵌着巧克力碎片，一口下去凉到鼻子里。喜欢它的人和讨厌它的人，常常会因为它吵起来。"},
    {"id":"choco_mint_macaron","no":541,"name":"巧克力薄荷马卡龙","emoji":"🍪","city":"france","ingredients":["mint","almond","chocolate"],"method":"cook","hint":"小小的圆饼夹着薄荷巧克力，外脆里软。","recipePrice":160,"sellPrice":80,"story":"原名 Macaron chocolat-menthe（法语）。杏仁粉做的小圆饼，夹着薄荷口味的巧克力酱。咬下去，先是脆壳，再是清凉的薄荷，最后是巧克力的甜。"},
    {"id":"choco_mint_daifuku","no":542,"name":"巧克力薄荷大福","emoji":"🍡","city":"japan","ingredients":["mint","chocolate","wheat_flour"],"method":"freeze","hint":"雪白软糯的皮里，是凉凉的薄荷巧克力。","recipePrice":260,"sellPrice":130,"story":"原名 チョコミント大福（日语）。雪白的大福皮包着薄荷巧克力馅，冰过以后更Q弹。传统和洋味一口吃到。"},
    {"id":"marshmallow_cocoa","no":543,"name":"棉花糖热巧克力","emoji":"☕","origin":"世界","ingredients":["chocolate","milk","sugar"],"method":"drink","hint":"热热的甜饮上漂着一层软软的小云朵。","recipePrice":140,"sellPrice":70,"story":"原名 Hot chocolate with marshmallows（英语）。冬天的夜里，一杯热巧克力，再丢几颗棉花糖。看着小云朵慢慢化开，手心和心里都是暖的。"},
    {"id":"mint_tea","no":544,"name":"薄荷茶","emoji":"🍃","city":"china","ingredients":["mint"],"method":"drink","hint":"绿绿的叶子，开水一冲，清清凉凉的香气就冒出来了。","recipePrice":120,"sellPrice":60,"story":"原名 Atay bi na'na'（阿拉伯语）。薄荷叶用开水一冲，是北非和中东人招待客人的方式。夏天喝是清凉，冬天喝是提神。"},
    {"id":"finnish_windmill_pie","no":545,"name":"芬兰圣诞风车派","emoji":"🎄","origin":"芬兰","ingredients":["butter_crust","blueberry"],"method":"cook","hint":"酥皮折成风车的样子，中间点缀着一点果子的紫。","recipePrice":120,"sellPrice":60,"story":"原名 Joulutorttu（芬兰语）。芬兰人在圣诞节会烤风车形状的星星派，酥皮四角折向中心，像一架旋转的小风车。"},
    {"id":"panettone","no":546,"name":"意大利潘妮托妮","emoji":"🍞","city":"italy","ingredients":["butter","wheat_flour","grape"],"method":"ferment","hint":"高高的圆顶面包，松软喷香，里面藏着一粒粒的果子。","recipePrice":160,"sellPrice":80,"story":"原名 Panettone（意大利语）。潘妮托妮是意大利圣诞节必备的发酵面包，要发酵好几天，里面加葡萄干，切开像一朵蓬松的云。"},
    {"id":"mexican_punch","no":547,"name":"墨西哥潘趣酒","emoji":"🍎","origin":"墨西哥","ingredients":["apple","cinnamon","sugar"],"method":"drink","hint":"热腾腾的果香，混着暖暖的香料气息。","recipePrice":120,"sellPrice":60,"story":"原名 Ponche navideño（西班牙语）。墨西哥人在圣诞节的夜晚，会在大锅里煮一锅水果和肉桂，大家围着一杯一杯地分。"},
    {"id":"danish_rice_pudding","no":548,"name":"丹麦大米布丁","emoji":"🍚","origin":"丹麦","ingredients":["rice","vanilla","almond"],"method":"freeze","hint":"凉凉的白色布丁，吃到藏在里面的杏仁有奖励。","recipePrice":280,"sellPrice":140,"story":"原名 Risalamande（丹麦语）。丹麦人在圣诞节吃米布丁，里面藏一颗整杏仁。谁吃到，谁就能得到一份小礼物。"},
    {"id":"cannelloni","no":549,"name":"加乃隆","emoji":"🍝","city":"italy","ingredients":["wheat_flour","pork","tomato"],"method":"cook","hint":"圆圆的面皮卷着馅，浇上红红的酱汁烤到冒泡。","recipePrice":140,"sellPrice":70,"story":"原名 Cannelloni（意大利语）。意大利人把肉馅用面皮卷起来，浇上番茄酱烤熟，是节日里一家人分享的一大盘。"},
    {"id":"xmas_ham","no":550,"name":"圣诞火腿","emoji":"🍖","origin":"世界","ingredients":["pork","honey","dough"],"method":"cook","hint":"亮晶晶的金黄外皮，切开是粉嫩的肉。","recipePrice":190,"sellPrice":95,"story":"原名 Christmas ham（英语）。圣诞节的餐桌上，一整只刷满蜂蜜的火腿是主角，用面团包着一起烤，肉汁都锁在里面。"},
    {"id":"xmas_roast_chicken","no":551,"name":"圣诞烤鸡","emoji":"🍗","origin":"世界","ingredients":["chicken","olive_oil"],"method":"cook","hint":"外皮金黄脆脆的，一刀下去，汁水满溢。","recipePrice":130,"sellPrice":65,"story":"原名 Christmas roast chicken（英语）。一只涂满橄榄油的烤鸡，端上圣诞桌的那一刻，整个房间都是香的。"},
    {"id":"grilled_corn","no":552,"name":"烤玉米","emoji":"🌽","city":"japan","ingredients":["corn","soy_sauce"],"method":"cook","hint":"刷上一层酱汁，在炭火上烤得焦香。","recipePrice":120,"sellPrice":60,"story":"原名 焼きとうもろこし（日语）。夏日祭典里最香的味道，酱油在玉米上烤出焦香，一下就把小朋友招来了。"},
    {"id":"yakitori","no":553,"name":"烤鸡肉串","emoji":"🍢","city":"japan","ingredients":["chicken","soy_sauce"],"method":"cook","hint":"一串串的小肉块，刷着酱汁，烤得滋滋冒油。","recipePrice":120,"sellPrice":60,"story":"原名 焼き鳥（日语）。居酒屋的炭火前，一串串鸡肉被反复刷上酱汁，是下班后最好的一口。"},
    {"id":"tamagoyaki_pancake","no":554,"name":"玉子煎饼","emoji":"🥞","city":"japan","ingredients":["shrimp","egg","nori"],"method":"cook","hint":"金黄的蛋饼里夹着小虾和海苔的香气。","recipePrice":200,"sellPrice":100,"story":"原名 玉子せんべい（日语）。在鸡蛋里加上小虾和海苔，煎成圆圆的薄饼，是夜市里一翻面就有人排队的小吃。"},
    {"id":"okonomiyaki","no":555,"name":"大阪烧","emoji":"🥘","city":"japan","ingredients":["wheat_flour","egg","pork"],"method":"cook","hint":"圆圆的大饼，铁板上滋滋作响，刷满酱汁和柴鱼花。","recipePrice":160,"sellPrice":80,"story":"原名 お好み焼き（日语）。大阪人的灵魂小吃，把面糊、鸡蛋和猪肉煎成饼，在铁板前吃，才最有味道。"},
    {"id":"yakisoba","no":556,"name":"日式炒面","emoji":"🍜","city":"japan","ingredients":["pork","noodles","ginger"],"method":"cook","hint":"一大盘油亮的面条，蒸汽里带着浓浓的酱香和姜味。","recipePrice":120,"sellPrice":60,"story":"原名 焼きそば（日语）。日本夏日祭典的摊位上，铁板炒面的味道总是最先飘过来。"},
    {"id":"creamy_potato","no":557,"name":"奶油马铃薯","emoji":"🥔","origin":"世界","ingredients":["potato","butter"],"method":"steam","hint":"蒸得粉粉的小土豆，上面一块牛油慢慢化开。","recipePrice":120,"sellPrice":60,"story":"原名 Buttered potatoes（英语）。最简单的做法：蒸熟的小土豆，加一块牛油。热气一冒，什么都不用再加。"},
    {"id":"fried_sanzi","no":558,"name":"炸馓子","emoji":"🥨","city":"china","ingredients":["noodles","consomme"],"method":"fry","hint":"一缕缕金黄酥脆的细丝，咬一口咔嚓作响。","recipePrice":130,"sellPrice":65,"story":"原名 馓子 Sǎnzi（汉语）。馓子是把面条拉成细丝盘成一团炸出来的，是中国北方的传统小吃，过节时必备。"},
    {"id":"rice_puff","no":559,"name":"米花","emoji":"🍘","city":"china","ingredients":["rice","sugar"],"method":"cook","hint":"蓬松香脆的白色小粒，一粒粒粘在一起。","recipePrice":120,"sellPrice":60,"story":"原名 米花 Mǐhuā（汉语）。把米炸得蓬松，再用糖浆粘成一块。是小时候过年时，总是藏在柜子里的小零嘴。"},
    {"id":"cheese_hotdog","no":560,"name":"芝士热狗","emoji":"🌭","city":"korea","ingredients":["sausage","cheese","wheat_flour"],"method":"fry","hint":"外面脆脆的，一咬就拉出长长的奶酪丝。","recipePrice":230,"sellPrice":115,"story":"原名 치즈 핫도그（韩语）。韩国街头的炸热狗，里面包着奶酪，一口咬下去，拉丝能拉出一尺长。"},
    {"id":"japanese_curry","no":561,"name":"咖喱饭","emoji":"🍛","city":"japan","ingredients":["onion","carrot","curry_powder"],"method":"cook","hint":"棕黄色的浓浓酱汁，盖在白饭上，热气腾腾。","recipePrice":120,"sellPrice":60,"story":"原名 カレーライス（日语）。咖喱经由英国传到日本，成了几乎每个家庭都会做的家常菜，是日本人的国民美食。"},
    {"id":"butter_chicken","no":562,"name":"黄油鸡肉咖喱","emoji":"🍛","origin":"印度","ingredients":["curry_powder","chicken","butter"],"method":"cook","hint":"橘红色的浓稠酱汁里，浸着嫩嫩的鸡肉。","recipePrice":160,"sellPrice":80,"story":"原名 Murgh Makhani（印地语）。印度德里的名菜，剩下的烤鸡被放进番茄和牛油酱里，意外成了最受欢迎的一道。"},
    {"id":"soup_curry_rice","no":563,"name":"咖喱汤饭","emoji":"🥣","city":"japan","ingredients":["pumpkin","curry_powder","consomme"],"method":"cook","hint":"汤里的咖喱香浓，南瓜软软的，米饭一泡就化开。","recipePrice":130,"sellPrice":65,"story":"原名 スープカレー（日语）。来自北海道札幌的咖喱，不是浓酱，而是一碗带着蔬菜的香辣汤，米饭泡着吃。"},
    {"id":"samosa","no":564,"name":"萨莫萨三角饺","emoji":"🔺","origin":"印度","ingredients":["potato","curry_powder","mint"],"method":"fry","hint":"金黄的三角形小包，咬开是热腾腾的香料土豆。","recipePrice":160,"sellPrice":80,"story":"原名 Samosa（印地语）。印度街头最常见的小吃，三角形的面皮包着土豆和香料，油炸后香脆酥软，常配薄荷酱吃。"},
    {"id":"tandoori_chicken","no":565,"name":"坦都里烤鸡","emoji":"🍗","origin":"印度","ingredients":["chicken","curry_powder","yogurt"],"method":"cook","hint":"红通通的烤鸡，外面带点焦，里面嫩得出汁。","recipePrice":150,"sellPrice":75,"story":"原名 Tandoori Chicken（印地语）。鸡肉用酸奶和香料腌过，放进泥炉里烤，红彤彤的外皮是它的标志。"},
    {"id":"curry_wedges","no":566,"name":"咖喱风味薯角","emoji":"🍟","origin":"世界","ingredients":["potato","curry_powder"],"method":"fry","hint":"金黄的小角，咬一口，香气先冲到鼻子里。","recipePrice":120,"sellPrice":60,"story":"原名 Curry potato wedges（英语）。把土豆切成角油炸，撒上咖喱粉，是配啤酒、追剧时最停不下来的小零食。"},
    {"id":"bagel","no":567,"name":"贝果","emoji":"🥯","origin":"世界","ingredients":["bagel_dough"],"method":"cook","hint":"圆圆的圈圈面包，又韧又有嚼劲。","recipePrice":120,"sellPrice":60,"story":"原名 Bagel（英语）。贝果要先用热水烫过再烤，所以外皮有光泽、里面特别有嚼劲，是纽约人的早餐。"},
    {"id":"sesame_bagel","no":568,"name":"芝麻贝果","emoji":"🥯","origin":"世界","ingredients":["bagel_dough","black_sesame"],"method":"cook","hint":"黑黑的芝麻粒铺满表面，一咬就香。","recipePrice":120,"sellPrice":60,"story":"原名 Sesame bagel（英语）。贝果表面铺满黑芝麻，烤过之后香气更浓，是贝果店里最经典的口味之一。"},
    {"id":"cocoa_bagel","no":569,"name":"可可贝果","emoji":"🥯","origin":"世界","ingredients":["cacao","bagel_dough"],"method":"cook","hint":"深褐色的圈圈，带着淡淡的可可香。","recipePrice":120,"sellPrice":60,"story":"原名 Cocoa bagel（英语）。把可可粉揉进面团里，烤出来是深深的褐色，微苦微甜，配咖啡很搭。"},
    {"id":"matcha_choco_bagel","no":570,"name":"抹茶巧克力贝果","emoji":"🥯","city":"japan","ingredients":["matcha","bagel_dough","chocolate"],"method":"cook","hint":"绿色的面团里，嵌着黑黑的巧克力碎。","recipePrice":190,"sellPrice":95,"story":"原名 抹茶チョコベーグル（日语）。日本面包店爱把抹茶和巧克力加进贝果里，苦与甜互相陪衬。"},
    {"id":"blueberry_bagel","no":571,"name":"蓝莓贝果","emoji":"🥯","origin":"世界","ingredients":["blueberry","bagel_dough"],"method":"cook","hint":"圈圈里藏着一粒粒蓝紫色的小果子。","recipePrice":120,"sellPrice":60,"story":"原名 Blueberry bagel（英语）。烤的时候蓝莓会爆开，把贝果染出一点点蓝紫色，酸酸甜甜。"},
    {"id":"rainbow_bagel","no":572,"name":"彩虹贝果","emoji":"🌈","city":"usa","ingredients":["food_coloring","bagel_dough","cream"],"method":"cook","hint":"一圈圈红橙黄绿蓝紫，抹着白白的奶油。","recipePrice":160,"sellPrice":80,"story":"原名 Rainbow bagel（英语）。彩虹贝果是纽约布鲁克林的发明，五颜六色，看一眼就想拍照。"},
    {"id":"strawberry_bagel_sandwich","no":573,"name":"草莓贝果三明治","emoji":"🍓","origin":"世界","ingredients":["bagel_dough","strawberry","cream"],"method":"cook","hint":"圈圈中间夹着红红的草莓和奶油。","recipePrice":190,"sellPrice":95,"story":"原名 Strawberry bagel sandwich（英语）。贝果横切开，夹满草莓和奶油，一口咬下去，酸、甜、嚼劲全都有。"},
    {"id":"honey_cream_cheese_bagel","no":574,"name":"奶油芝士蜂蜜贝果","emoji":"🍯","city":"usa","ingredients":["bagel_dough","cheese","honey"],"method":"direct","hint":"涂满奶酪和蜂蜜，咸里带甜。","recipePrice":180,"sellPrice":90,"story":"原名 Bagel with honey and cream cheese（英语）。贝果配奶油奶酪是纽约最经典的搭配，再淋一点蜂蜜，就是一份甜口版本。"},
    {"id":"herring_bagel_sandwich","no":575,"name":"鲱鱼贝果三明治","emoji":"🐟","origin":"北欧","ingredients":["bagel_dough","herring","onion"],"method":"direct","hint":"咸香的小鱼，配上洋葱的辛辣，很有北欧的味道。","recipePrice":180,"sellPrice":90,"story":"原名 Sillbagel（瑞典语）。北欧人爱把腌鲱鱼配洋葱放在面包上，放进贝果里，意外地合适。"},
    {"id":"avocado_bagel_sandwich","no":576,"name":"牛油果贝果三明治","emoji":"🥑","city":"usa","ingredients":["cheese","avocado","bagel_dough"],"method":"direct","hint":"绿绿的果肉抹在贝果上，又滑又香。","recipePrice":200,"sellPrice":100,"story":"原名 Avocado bagel sandwich（英语）。牛油果泥、奶油奶酪、再加一个贝果，是美国咖啡馆里最时髦的早午餐。"},
    {"id":"naan","no":577,"name":"馕","emoji":"🫓","city":"china","ingredients":["dough","yogurt","olive_oil"],"method":"cook","hint":"圆圆的大饼，表面起了焦黄的泡泡，外脆里软。","recipePrice":190,"sellPrice":95,"story":"原名 Nan（维吾尔语）。馕是中亚和新疆人的主食，在馕坑里贴着烤，一个能放很久，出门远行都带着它。"},
    {"id":"babka","no":578,"name":"巴布卡","emoji":"🍫","origin":"波兰","ingredients":["cinnamon","chocolate","danish"],"method":"cook","hint":"一圈圈扭成麻花的面包，切开是深浅交错的螺旋。","recipePrice":150,"sellPrice":75,"story":"原名 Babka（波兰语）。巴布卡是东欧犹太人的节日面包，面团里卷上巧克力和肉桂，扭一扭再烤，切开像一幅画。"},
    {"id":"berliner","no":579,"name":"柏林果酱包","emoji":"🍩","origin":"德国","ingredients":["sugar","grape","wheat_flour"],"method":"fry","hint":"圆滚滚的炸面包，撒着白糖，里面包着满满的果酱。","recipePrice":160,"sellPrice":80,"story":"原名 Berliner / Pfannkuchen（德语）。德国人在新年和狂欢节吃它，吃的时候要小心，果酱会从里面挤出来。"},
    {"id":"pao_de_queijo","no":580,"name":"巴西芝士面包","emoji":"🧀","origin":"巴西","ingredients":["milk","wheat_flour","cheese"],"method":"cook","hint":"小小圆圆的一颗，外面脆，里面又糯又会拉丝。","recipePrice":170,"sellPrice":85,"story":"原名 Pão de queijo（葡萄牙语）。巴西的国民小吃，没有用酵母，靠奶酪把面团撑得鼓鼓的，一口一个。"},
    {"id":"mantou","no":581,"name":"馒头","emoji":"🍞","city":"china","ingredients":["dough"],"method":"steam","hint":"白白胖胖的圆面包，热气一冒，满是麦香。","recipePrice":120,"sellPrice":60,"story":"原名 馒头 Mántou（汉语）。蒸出来的白面包，北方人的主食，什么都能配，或者什么都不配也好吃。"},
    {"id":"french_spice_bread","no":582,"name":"法式香料面包","emoji":"🍞","city":"france","ingredients":["cinnamon","honey","rye"],"method":"cook","hint":"深褐色的面包，闻起来有蜂蜜和香料的暖香。","recipePrice":120,"sellPrice":60,"story":"原名 Pain d'épices（法语）。法国人把黑麦、蜂蜜和香料揉在一起做成的老面包，冬天吃，最能暖身子。"},
    {"id":"smores","no":583,"name":"烤棉花糖夹心饼干","emoji":"🔥","city":"usa","ingredients":["sugar","rye","chocolate"],"method":"cook","hint":"烤得焦焦软软的甜，夹在两片脆脆的饼里。","recipePrice":120,"sellPrice":60,"story":"原名 S'mores（英语）。美国露营的篝火边，一定会有它。棉花糖烤到半融，夹上巧克力，再用饼干一压。"},
    {"id":"baked_sweet_potato","no":584,"name":"烤红薯","emoji":"🍠","city":"japan","ingredients":["sweet_potato"],"method":"cook","hint":"外皮焦焦的，一掰开是金黄流蜜的软糯。","recipePrice":120,"sellPrice":60,"story":"原名 焼き芋（日语）。冬天街头最香的东西，烤红薯车的叫卖声一响，大家都忍不住循着香味找过去。"},
    {"id":"choco_fondue","no":585,"name":"水果巧克力火锅","emoji":"🍫","origin":"世界","ingredients":["raw_chocolate","mango","strawberry"],"method":"cook","hint":"一锅热热的巧克力，什么水果丢进去都变得更好吃。","recipePrice":220,"sellPrice":110,"story":"原名 Chocolate fondue（英语）。瑞士人最早在冬天用火锅融化奶酪，后来人们把巧克力放进去，蘸着水果吃。"},
    {"id":"rose_icecream","no":586,"name":"冰淇淋玫瑰","emoji":"🌹","origin":"世界","ingredients":["cream","sugar","edible_rose"],"method":"freeze","hint":"一朵朵花瓣一样的冰淇淋，粉粉的，香香的。","recipePrice":300,"sellPrice":150,"story":"原名 Rose ice cream（英语）。用勺子把冰淇淋一层层刮成花瓣，摆成一朵玫瑰。舍不得吃，又怕它化掉。"},
    {"id":"rose_macaron","no":587,"name":"玫瑰马卡龙","emoji":"🌹","city":"france","ingredients":["almond","sugar","edible_rose"],"method":"cook","hint":"小小的粉色圆饼，咬一口，满嘴都是花香。","recipePrice":150,"sellPrice":75,"story":"原名 Macaron à la rose（法语）。巴黎甜点店里的玫瑰马卡龙，夹着玫瑰奶油，是最浪漫的那一款。"},
    {"id":"rose_choco_tart","no":588,"name":"玫瑰巧克力挞","emoji":"🌹","city":"france","ingredients":["raw_chocolate","butter_crust","edible_rose"],"method":"cook","hint":"浓浓的巧克力上面，铺着一片片玫瑰花瓣。","recipePrice":210,"sellPrice":105,"story":"原名 Tarte au chocolat et à la rose（法语）。酥脆的挞皮里装满浓郁的巧克力，再点缀玫瑰花瓣，苦、甜、花香三味合一。"},
    {"id":"rose_jelly","no":589,"name":"玫瑰果冻","emoji":"🌹","origin":"世界","ingredients":["gelatin","apple","edible_rose"],"method":"freeze","hint":"粉红透亮的果冻里，漂着几片花瓣。","recipePrice":280,"sellPrice":140,"story":"原名 Rose jelly（英语）。玫瑰花瓣漂在透明的果冻里，一口咬下去，是苹果的清甜和花的香气。"},
    {"id":"rose_jam","no":590,"name":"玫瑰果酱","emoji":"🌹","origin":"世界","ingredients":["sugar","lemon","edible_rose"],"method":"cook","hint":"深粉红色的酱，抹在面包上，有春天的香气。","recipePrice":140,"sellPrice":70,"story":"原名 Rose jam（英语）。把玫瑰花瓣和柠檬、糖一起慢慢熬，熬成粉红色的酱，一小勺就满是花香。"},
    {"id":"rose_tea","no":591,"name":"玫瑰花茶","emoji":"🌹","city":"china","ingredients":["water","edible_rose"],"method":"drink","hint":"干花泡开，粉红色的花瓣在杯里慢慢舒展。","recipePrice":120,"sellPrice":60,"story":"原名 玫瑰花茶 Méiguī huāchá（汉语）。中国人喜欢用玫瑰花泡茶，据说能让人心情变好，喝起来有淡淡的甜香。"},
    {"id":"thanksgiving_cornbread","no":592,"name":"感恩节玉米面包","emoji":"🌽","city":"usa","ingredients":["butter","corn","baking_powder"],"method":"cook","hint":"金黄的松软小方块，咬开有玉米粒的甜，配热汤最好。","recipePrice":120,"sellPrice":60,"story":"原名 Cornbread（英语）。美国人在感恩节晚餐的桌上，总少不了一块金黄的玉米面包。它来自原住民教给早期移民的玉米吃法，配火鸡和热汤，一家人围坐分食。"},
    {"id":"seafood_paella","no":593,"name":"海鲜西班牙海鲜饭","emoji":"🥘","origin":"西班牙","ingredients":["rice","shrimp","lemon"],"method":"cook","hint":"一口大平锅，金黄的米粒吸满了海的鲜味，锅底还有一层焦香。","recipePrice":160,"sellPrice":80,"story":"原名 Paella de marisco（西班牙语）。西班牙瓦伦西亚的名菜，在宽宽的平底锅里把米和海鲜一起煮熟，最后挤上柠檬汁。锅底那层焦脆的米，叫“索卡拉”，是最抢手的一口。"},
    {"id":"chicken_paella","no":594,"name":"鸡肉西班牙海鲜饭","emoji":"🍗","origin":"西班牙","ingredients":["rice","chicken","lemon"],"method":"cook","hint":"金黄的米饭里嵌着嫩嫩的肉块，挤一点酸，越吃越香。","recipePrice":120,"sellPrice":60,"story":"原名 Paella de pollo（西班牙语）。海鲜饭的陆地版本，用鸡肉代替海鲜，一样煮得米粒饱满、锅底焦香。不爱吃海鲜的人，也能围着大锅一起吃。"},
    {"id":"yunnan_flower_cake","no":595,"name":"云南鲜花饼","emoji":"🌸","city":"china","ingredients":["butter_crust","edible_rose","honey"],"method":"cook","hint":"酥酥的小圆饼，一掰开，里面是粉红的花瓣和蜜。","recipePrice":190,"sellPrice":95,"story":"原名 鲜花饼 Xiānhuā bǐng（汉语）。云南人用当地盛开的玫瑰花瓣和蜂蜜做馅，包进层层酥皮里烤成小圆饼。一口咬下去，酥脆之后是花的香气，是游客从昆明带回家的伴手礼。"},
    {"id":"pineapple_gulaorou","no":596,"name":"菠萝咕咾肉","emoji":"🍍","city":"china","ingredients":["pork","starch","pineapple"],"method":"fry","hint":"金黄酥脆的肉块，裹着亮晶晶的酸甜汁，一口咬下去还有清爽的果香。","recipePrice":220,"sellPrice":110,"story":"原名 菠萝咕咾肉 Bōluó gūlǎoròu（汉语）。咕咾肉是粤菜里的酸甜名菜，相传外国客人爱吃酸甜口，厨师便把炸得酥脆的肉块淋上糖醋汁，再配上菠萝和彩椒一起翻炒。红红黄黄的一大盘端上桌，是全家聚餐时最先被夹光的那道。"}
